    10→import { toast } from "sonner";
    11→import { Save, Loader2, Bot, RotateCcw, Copy, ExternalLink } from "lucide-react";
    12→import { logAuditAction } from "@/lib/auditLog";
    13→
    14→const DEFAULT_ROBOTS = `User-agent: *
    15→Allow: /
    16→
    17→# Block admin and auth pages from crawling
    18→Disallow: /admin
    19→Disallow: /settings
    20→
    21→# Allow social media crawlers
    22→User-agent: Googlebot
    23→Allow: /
    24→
    25→User-agent: Bingbot
    26→Allow: /
    27→
    28→User-agent: Twitterbot
    29→Allow: /
    30→
    31→User-agent: facebookexternalhit
    32→Allow: /
    33→
    34→Sitemap: /sitemap.xml`;
    35→
    36→const RobotsTxtTab = () => {
    37→  const qc = useQueryClient();
    38→  const { settings, isLoading } = useSeoSettings();
    39→  const [saving, setSaving] = useState(false);
    40→  const [loaded, setLoaded] = useState(false);
    41→
    42→  const [form, setForm] = useState({
    43→    robots_txt: "",
    44→    googlebot: "",
    45→    bingbot: "",
    46→  });
    47→
    48→  if (settings && !loaded) {
    49→    setForm({
    50→      robots_txt: settings.robots_txt ?? DEFAULT_ROBOTS,
    51→      googlebot: settings.googlebot ?? "",
    52→      bingbot: settings.bingbot ?? "",
    53→    });
    54→    setLoaded(true);
    55→  }
    56→
    57→  const save = async () => {
    58→    setSaving(true);
    59→    try {
    60→      const { error } = await (supabase as any)
    61→        .from("seo_settings")
    62→        .update(form)
    63→        .eq("id", settings?.id);
    64→      if (error) { toast.error(error.message); return; }
    65→      toast.success("Robots.txt settings saved");
    66→      logAuditAction("seo.update", "seo_settings", settings?.id, { section: "robots" });
    67→      qc.invalidateQueries({ queryKey: ["seo_settings"] });
    68→    } finally {
    69→      setSaving(false);
    70→    }
    71→  };
    72→
    73→  const resetToDefault = () => {
    74→    setForm({ ...form, robots_txt: DEFAULT_ROBOTS });
    75→    toast.info("Reset to default. Click Save to apply.");
    76→  };
    77→
    78→  if (isLoading) return <div className="flex items-center gap-2 text-muted-foreground"><Loader2 className="h-4 w-4 animate-spin" /> Loading...</div>;
    79→
    80→  return (
    81→    <div className="space-y-4">
    82→      <Card>
    83→        <CardHeader className="pb-3">
    84→          <div className="flex items-center justify-between">
    85→            <div>
    86→              <CardTitle className="text-lg flex items-center gap-2"><Bot className="h-5 w-5" /> Robots.txt Editor</CardTitle>
    87→              <CardDescription>Controls which pages search engine bots can crawl. This content will be served at /robots.txt</CardDescription>
    88→            </div>
    89→            <Button variant="outline" size="sm" onClick={resetToDefault}>
    90→              <RotateCcw className="h-3 w-3 mr-1" /> Reset to Default
    91→            </Button>
    92→          </div>
    93→        </CardHeader>
    94→        <CardContent className="space-y-4">
    95→          <Textarea
    96→            value={form.robots_txt}
    97→            onChange={(e) => setForm({ ...form, robots_txt: e.target.value })}
    98→            className="min-h-[300px] font-mono text-sm"
    99→            placeholder="User-agent: *\nAllow: /"
   100→          />
   101→          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
   102→            <div>
   103→              <Label>Googlebot Specific Directive</Label>
   104→              <Input value={form.googlebot} onChange={(e) => setForm({ ...form, googlebot: e.target.value })} placeholder="e.g. noindex, nofollow (leave empty for default)" />
   105→              <p className="text-xs text-muted-foreground mt-1">Added as &lt;meta name="googlebot"&gt; if set</p>
   106→            </div>
   107→            <div>
   108→              <Label>Bingbot Specific Directive</Label>
   109→              <Input value={form.bingbot} onChange={(e) => setForm({ ...form, bingbot: e.target.value })} placeholder="e.g. noindex (leave empty for default)" />
   110→              <p className="text-xs text-muted-foreground mt-1">Added as &lt;meta name="bingbot"&gt; if set</p>
   111→            </div>
   112→          </div>
   113→        </CardContent>
   114→      </Card>
   115→
   116→      <Button onClick={save} disabled={saving}>
   117→        {saving ? <Loader2 className="h-4 w-4 mr-1 animate-spin" /> : <Save className="h-4 w-4 mr-1" />}
   118→        Save Robots Settings
   119→      </Button>
   120→
   121→      {/* Live endpoint info */}
   122→      <Card className="border-dashed bg-muted/30">
   123→        <CardHeader className="pb-2 pt-4">
   124→          <CardTitle className="text-sm">Dynamic Endpoint</CardTitle>
   125→          <CardDescription className="text-xs">
   126→            Changes saved here are served live from this Supabase Edge Function URL.
   127→            Configure a rewrite rule on your production domain so <code className="bg-muted px-1 rounded text-xs">/robots.txt</code> proxies to this endpoint, or serve it directly from the URL below.
   128→          </CardDescription>
   129→        </CardHeader>
   130→        <CardContent className="pb-4 space-y-2">
   131→          <div className="flex items-center gap-2 rounded-md bg-muted px-3 py-2">
   132→            <code className="text-xs font-mono flex-1 break-all text-muted-foreground">
   133→              https://zkzontawprihrzpayeam.supabase.co/functions/v1/serve-robots
   134→            </code>
   135→            <Button
   136→              variant="ghost" size="icon" className="h-7 w-7 shrink-0"
   137→              onClick={() => { navigator.clipboard.writeText("https://zkzontawprihrzpayeam.supabase.co/functions/v1/serve-robots"); toast.success("URL copied"); }}
   138→            >
   139→              <Copy className="h-3.5 w-3.5" />
   140→            </Button>
   141→            <Button variant="ghost" size="icon" className="h-7 w-7 shrink-0" asChild>
   142→              <a href="https://zkzontawprihrzpayeam.supabase.co/functions/v1/serve-robots" target="_blank" rel="noopener noreferrer">
   143→                <ExternalLink className="h-3.5 w-3.5" />
   144→              </a>
   145→            </Button>
   146→          </div>
   147→        </CardContent>
   148→      </Card>
   149→    </div>
   150→  );
   151→};
   152→
   153→export default RobotsTxtTab;
   154→

