    15→const SitemapTab = () => {
    16→  const qc = useQueryClient();
    17→  const { settings, isLoading } = useSeoSettings();
    18→  const { pages } = useSeoPages();
    19→  const [saving, setSaving] = useState(false);
    20→  const [loaded, setLoaded] = useState(false);
    21→  const [showPreview, setShowPreview] = useState(false);
    22→
    23→  const [form, setForm] = useState({
    24→    sitemap_enabled: true,
    25→    sitemap_changefreq: "weekly",
    26→    sitemap_priority: 0.8,
    27→  });
    28→
    29→  if (settings && !loaded) {
    30→    setForm({
    31→      sitemap_enabled: settings.sitemap_enabled ?? true,
    32→      sitemap_changefreq: settings.sitemap_changefreq ?? "weekly",
    33→      sitemap_priority: settings.sitemap_priority ?? 0.8,
    34→    });
    35→    setLoaded(true);
    36→  }
    37→
    38→  const save = async () => {
    39→    setSaving(true);
    40→    try {
    41→      const { error } = await (supabase as any)
    42→        .from("seo_settings")
    43→        .update(form)
    44→        .eq("id", settings?.id);
    45→      if (error) { toast.error(error.message); return; }
