const LLMS_TXT_ENDPOINT = "https://zkzontawprihrzpayeam.supabase.co/functions/v1/serve-llms-txt";

const AeoGeoTab = () => {
  const qc = useQueryClient();
  const { settings, isLoading } = useSeoSettings();
  const [saving, setSaving] = useState(false);
  const [loaded, setLoaded] = useState(false);
  const [showLlmsPreview, setShowLlmsPreview] = useState(false);

  const [form, setForm] = useState({
    // AEO
    aeo_enabled: false,
    aeo_speakable_enabled: false,
    aeo_faq_json: [] as FaqItem[],
    // GEO
    geo_enabled: false,
    geo_site_description_for_ai: "",
    geo_author_name: "",
    geo_author_url: "",
    geo_citations_enabled: false,
    geo_llms_txt: "",
  });

  if (settings && !loaded) {
    setForm({
      aeo_enabled: settings.aeo_enabled ?? false,
      aeo_speakable_enabled: settings.aeo_speakable_enabled ?? false,
      aeo_faq_json: Array.isArray(settings.aeo_faq_json) ? settings.aeo_faq_json : [],
      geo_enabled: settings.geo_enabled ?? false,
      geo_site_description_for_ai: settings.geo_site_description_for_ai ?? "",
      geo_author_name: settings.geo_author_name ?? "",
      geo_author_url: settings.geo_author_url ?? "",
      geo_citations_enabled: settings.geo_citations_enabled ?? false,
