  }

  const generateDefaultLlmsTxt = () => {
    const siteTitle = settings?.site_title || "Rankora";
    const siteDescription = settings?.site_description || "AI-powered resume screening and candidate ranking platform.";
    const canonicalUrl = (settings?.canonical_url || "").replace(/\/$/, "") || "https://rankora.com";
    const authorName = form.geo_author_name || siteTitle;

    const content = `# ${siteTitle}

> ${siteDescription}

## About

${form.geo_site_description_for_ai || siteDescription}

