                    className="mt-1"
                  />
                  <p className="text-xs text-muted-foreground mt-1">Used in citation_author_institution_url meta tag</p>
                </div>
              </div>

              {/* Citation meta toggle */}
              <div className="flex items-center gap-3">
                <Switch
                  id="geo-citations"
                  checked={form.geo_citations_enabled}
                  onCheckedChange={(v) => setForm({ ...form, geo_citations_enabled: v })}
                />
                <div>
                  <Label htmlFor="geo-citations">Enable Citation Meta Tags</Label>
                  <p className="text-xs text-muted-foreground mt-0.5">
                    Adds citation_title and max-snippet:-1 robots directive so AI engines can use full snippets as citations.
                  </p>
                </div>
              </div>

              {/* llms.txt */}
              <div>
                <div className="flex items-center justify-between mb-1">
                  <div>
                    <Label>llms.txt Content</Label>
                    <p className="text-xs text-muted-foreground mt-0.5">
                      Emerging standard for AI crawlers. Served at{" "}
                      <code className="bg-muted px-1 rounded text-xs">/llms.txt</code>{" "}
                      via the edge function below. Tells AI engines what your site does and what they may use.
                    </p>
                  </div>
                  <Button
                    variant="outline"
                    size="sm"
                    onClick={generateDefaultLlmsTxt}
                    className="shrink-0 ml-4"
                  >
                    <Wand2 className="h-3.5 w-3.5 mr-1" /> Generate Default
                  </Button>
                </div>
                <Textarea
                  value={form.geo_llms_txt}
                  onChange={(e) => setForm({ ...form, geo_llms_txt: e.target.value })}
                  placeholder="# Rankora&#10;&#10;> AI-powered resume screening platform..."
                  className="min-h-[200px] font-mono text-sm mt-1"
                />
              </div>

              {/* llms.txt preview */}
              {form.geo_llms_txt && (
                <div>
                  <Button
                    variant="ghost"
                    size="sm"
                    onClick={() => setShowLlmsPreview(!showLlmsPreview)}
                    className="text-xs text-muted-foreground"
