                    <pre className="mt-2 text-xs font-mono bg-muted p-3 rounded-md overflow-auto max-h-64 whitespace-pre-wrap">
                      {form.geo_llms_txt}
                    </pre>
                  )}
                </div>
              )}
            </>
          )}
        </CardContent>
      </Card>

      {/* Save */}
      <Button onClick={save} disabled={saving}>
        {saving ? <Loader2 className="h-4 w-4 mr-1 animate-spin" /> : <Save className="h-4 w-4 mr-1" />}
        Save AEO / GEO Settings
      </Button>

      {/* llms.txt endpoint info */}
      <Card className="border-dashed bg-muted/30">
        <CardHeader className="pb-2 pt-4">
          <CardTitle className="text-sm">llms.txt Dynamic Endpoint</CardTitle>
          <CardDescription className="text-xs">
            The llms.txt content is served live from this Supabase Edge Function URL.
            Configure a rewrite rule on your production domain so{" "}
            <code className="bg-muted px-1 rounded text-xs">/llms.txt</code> proxies to this endpoint,
            or reference it directly.
          </CardDescription>
        </CardHeader>
        <CardContent className="pb-4 space-y-2">
          <div className="flex items-center gap-2 rounded-md bg-muted px-3 py-2">
            <code className="text-xs font-mono flex-1 break-all text-muted-foreground">
              {LLMS_TXT_ENDPOINT}
