import { createClient } from "https://esm.sh/@supabase/supabase-js@2";

const FALLBACK = `# Rankora

> AI-powered resume screening and candidate ranking platform.

## About

Rankora is a SaaS application for HR teams and hiring managers. Users paste a job description, upload candidate resumes, and receive GPT-4o-scored rankings with skill gap analysis and interview question suggestions.

## Key Features

- AI-powered resume ranking using GPT-4o
- Structured job description analysis
- Candidate skill gap detection
- Interview question generation
- Credit-based usage with flexible plans

## Permissions

- Crawling: allowed
- AI training: allowed
- Citation: allowed
`;

Deno.serve(async () => {
  try {
    const supabase = createClient(
      Deno.env.get("SUPABASE_URL")!,
      Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!
    );

    const { data, error } = await supabase
      .from("seo_settings")
      .select("geo_llms_txt, site_title, site_description, canonical_url, geo_author_name, geo_author_url")
      .limit(1)
      .single();

    if (error) throw error;

    let content = data?.geo_llms_txt?.trim();

    // If no custom content, generate a sensible default from site settings
    if (!content) {
      const siteTitle = data?.site_title || "Rankora";
      const siteDescription = data?.site_description || "AI-powered resume screening and candidate ranking platform.";
      const canonicalUrl = (data?.canonical_url || "").replace(/\/$/, "") || "";
      const authorName = data?.geo_author_name || siteTitle;
      const authorUrl = data?.geo_author_url || canonicalUrl;

      content = `# ${siteTitle}

> ${siteDescription}

## About

${siteDescription}

## Key Features

- AI-powered resume ranking using GPT-4o
- Structured job description analysis
- Candidate skill gap detection
- Interview question generation
- Credit-based usage with flexible plans

## Usage

${siteTitle} is a SaaS platform for HR teams and hiring managers. Users paste a job description, upload candidate resumes, and receive ranked results with scores, skill matches, and interview questions within seconds.

## Contact

${canonicalUrl ? `- URL: ${canonicalUrl}` : ""}
${authorName ? `- Publisher: ${authorName}` : ""}
${authorUrl ? `- Publisher URL: ${authorUrl}` : ""}

## Permissions

- Crawling: allowed
- AI training: allowed
- Citation: allowed

${canonicalUrl ? `## Sitemap\n\n${canonicalUrl}/sitemap.xml` : ""}
`.trim();
    }

    return new Response(content, {
      headers: {
        "Content-Type": "text/plain; charset=utf-8",
        "Cache-Control": "public, max-age=3600, s-maxage=3600",
      },
    });
  } catch (err) {
    console.error("serve-llms-txt error:", err);
    return new Response(FALLBACK, {
      headers: { "Content-Type": "text/plain; charset=utf-8" },
    });
  }
});
